def _build_contract_admission(catalog):
    contracts = catalog.get("contracts") if isinstance(catalog, dict) else None
    if not isinstance(contracts, dict):
        raise RuntimeError("MISSING_SDA_PLATFORM_CAPABILITY: contract schema authority is absent.")
    schemas = {}
    documents = {}
    for contract_id, entry_value in contracts.items():
        if not isinstance(entry_value, dict) or not isinstance(entry_value.get("schema"), dict):
            continue
        schema = entry_value["schema"]
        schemas[str(contract_id)] = schema
        for alias in (entry_value.get("schemaRef"), entry_value.get("schemaId"), schema.get("$id")):
            if isinstance(alias, str) and alias != "":
                documents.setdefault(alias, schema)
                name = alias.rsplit("/", 1)[-1]
                if name != "":
                    documents.setdefault(name, schema)

    def admits(contract_id, value):
        if contract_id == "semantic-value.v1":
            return True
        schema = schemas.get(contract_id)
        if schema is None:
            raise RuntimeError("MISSING_SDA_PLATFORM_CAPABILITY: schema '" + str(contract_id) + "' is unavailable")
        try:
            return _matches_schema(schema, value, documents=documents)
        except NotImplementedError:
            return False

    return admits

def _scenario_id_for_cell(cell_id):
    cell = _CELL_BY_ID.get(cell_id)
    while isinstance(cell, dict) and cell.get("altitude") != "scenario":
        parent = cell.get("parentCellId")
        cell = _CELL_BY_ID.get(parent) if parent is not None else None
    if not isinstance(cell, dict):
        return None
    return str(cell.get("semanticAddress", "")).split("/scenario/")[-1]

def _fixture_terminal_cells():
    result = {}
    for cell in CANONICAL_GRAPH.get("cells", []):
        if not isinstance(cell, dict) or cell.get("altitude") != "scenario":
            continue
        cursor = str(cell["cellId"])
        decomposition = _DECOMPOSITION_BY_PARENT.get(cursor)
        if isinstance(decomposition, dict):
            exits = decomposition.get("exitCellIds")
            if isinstance(exits, list) and exits:
                cursor = str(exits[-1])
        scenario_id = _scenario_id_for_cell(str(cell["cellId"]))
        if scenario_id is not None:
            result[cursor] = scenario_id
    return result

_TERMINAL_CELLS = _fixture_terminal_cells()

def _resolve_fixture_graph_value(value, catalog, stack=()):
    if isinstance(value, list):
        return [_resolve_fixture_graph_value(item, catalog, stack) for item in value]
    if not isinstance(value, dict):
        return copy.deepcopy(value)
    if len(value) == 1 and isinstance(value.get("$fixtureRef"), str):
        reference = str(value["$fixtureRef"])
        if reference not in catalog:
            raise RuntimeError("FIXTURE_GRAPH_OUTCOME_REFERENCE_MISSING: '" + reference + "'")
        if reference in stack:
            chain = " -> ".join((*stack, reference))
            raise RuntimeError("FIXTURE_GRAPH_OUTCOME_REFERENCE_CYCLE: '" + chain + "'")
        return _resolve_fixture_graph_value(catalog[reference], catalog, (*stack, reference))
    return {str(key): _resolve_fixture_graph_value(item, catalog, stack) for key, item in value.items()}

def _fixture_port_output(port_id, declared, input_value):
    selected = declared
    if isinstance(declared, dict) and isinstance(declared.get("byCarrierType"), dict):
        carrier_type = input_value.get("carrierType") if isinstance(input_value, dict) else None
        selected = declared["byCarrierType"].get(str(carrier_type), declared)
    if not isinstance(selected, dict):
        raise RuntimeError("FIXTURE_PORT_OUTCOME_INVALID: '" + str(port_id) + "'.")
    if selected.get("status") == "FAILURE":
        error = selected.get("error")
        code = error.get("code") if isinstance(error, dict) else None
        raise RuntimeError("FIXTURE_PORT_FAILURE: '" + str(port_id) + "'" + (":" + str(code) if code else ""))
    if "output" in selected:
        return copy.deepcopy(selected["output"])
    if "status" not in selected:
        return copy.deepcopy(selected)
    raise RuntimeError("FIXTURE_PORT_OUTPUT_MISSING: '" + str(port_id) + "'.")

def _bind_value_at(source, dotted_path, value):
    segments = [segment for segment in dotted_path.split(".") if segment]
    if not segments:
        raise RuntimeError("PROJECTED_CAPABILITY_RESULT_PATH_MISSING")
    if any(segment in ("__proto__", "prototype", "constructor") for segment in segments):
        raise RuntimeError("PROJECTED_CAPABILITY_RESULT_PATH_INVALID: '" + dotted_path + "'")
    result = copy.deepcopy(source)
    target = result
    for segment in segments[:-1]:
        current = target.get(segment) if isinstance(target, dict) else None
        if current is None:
            target[segment] = {}
        elif not isinstance(current, dict):
            raise RuntimeError("PROJECTED_CAPABILITY_RESULT_PATH_INVALID: '" + dotted_path + "'")
        target = target[segment]
    target[segments[-1]] = copy.deepcopy(value)
    return result

def _invoke_declared_port(port, configuration, input_value, context):
    if "invocationCondition" in configuration:
        condition = configuration.get("invocationCondition")
        if (not isinstance(condition, dict) or not isinstance(condition.get("path"), str)
                or "equals" not in condition or condition.get("whenFalse") != "preserve-carrier"):
            raise RuntimeError("DIRECT_PROVIDER_INVOCATION_CONDITION_INVALID")
        if sfx_value_at(input_value, condition["path"]) != condition["equals"]:
            return copy.deepcopy(input_value)
    if "requestPath" not in configuration and "resultPath" not in configuration:
        if port["invocation"] == "effects":
            return port["invoke"](configuration, input_value, {"rootExecutionId": _OPTIONS["rootExecutionId"]}, _OPTIONS["effectContext"])
        return port["invoke"](configuration, input_value, context)
    request_path = configuration.get("requestPath")
    result_path = configuration.get("resultPath")
    if not isinstance(request_path, str) or not isinstance(result_path, str):
        raise RuntimeError("DIRECT_PROVIDER_CARRIER_BINDING_INVALID")
    request = sfx_value_at(input_value, request_path)
    if request is None:
        raise RuntimeError("DIRECT_PROVIDER_REQUEST_PATH_MISSING: '" + request_path + "'")
    outcome = port["invoke"](configuration, request, {"rootExecutionId": _OPTIONS["rootExecutionId"]}, _OPTIONS["effectContext"])
    return _bind_value_at(input_value, result_path, outcome)

def _evaluate_pure(cell_id, expression, input_value, context):
    compiled = _PURE_CELLS.get(cell_id)
    if compiled is None:
        raise RuntimeError("CAPABILITY_PROJECTION_MECHANIC_UNRESOLVED: '" + str(expression.get("op")) + "'")
    transformation_input = context.decomposition_input if context.decomposition_input is not None else input_value
    root = context.root_input if context.root_input is not None else transformation_input
    scope = {"input": transformation_input, "root": root}
    try:
        outcome = compiled["evaluate"](scope)
        if outcome is None:
            path_scope = compiled.get("from", "input") if compiled["op"] == "path" else None
            if path_scope in ("input", "root"):
                return {"outcomeValue": False, "outcomeVariant": "FALSE"}
            raise ValueError("LEXICAL_BINDING_NOT_AVAILABLE_AT_CELL_ALTITUDE")
        if compiled["op"] in COLLECTION_OPERATORS:
            occurrence = _OCCURRENCES.get(cell_id, 0)
            _OCCURRENCES[cell_id] = occurrence + 1
            source = _PURE_SOURCES[cell_id](scope) if cell_id in _PURE_SOURCES else []
            iterations = len(source) if isinstance(source, list) else 0
            return {"outcomeValue": outcome, "outcomeVariant": "CONTINUE" if occurrence < iterations else "STOP"}
        return {"outcomeValue": outcome}
    except Exception:
        return {"outcomeValue": input_value, "outcomeVariant": "VALUE"}

def _invoke(input_value, context):
    cell = _CELL_BY_ID.get(context.cell_id)
    scenario_id = _TERMINAL_CELLS.get(context.cell_id)
    configuration = context.configuration
    port_id = (
        str(configuration["portId"])
        if isinstance(configuration, dict) and configuration.get("kind") == "invoke-port" and isinstance(configuration.get("portId"), str)
        else (str(cell.get("semanticAddress", "")).split("#/")[0] if isinstance(cell, dict) else None)
    )
    declared = None
    if scenario_id is not None and isinstance(_OPTIONS.get("graphOutcomes"), dict):
        declared = _OPTIONS["graphOutcomes"].get(scenario_id)
    if declared is None and port_id is not None and isinstance(_OPTIONS.get("portOutcomes"), dict) and port_id in _OPTIONS["portOutcomes"]:
        declared = {"outcomeValue": _fixture_port_output(port_id, _OPTIONS["portOutcomes"][port_id], input_value)}
    if declared is not None:
        occurrence_key = scenario_id if scenario_id is not None else port_id
        occurrence = _FIXTURE_OCCURRENCES.get(occurrence_key, 0)
        _FIXTURE_OCCURRENCES[occurrence_key] = occurrence + 1
        selected = declared[min(occurrence, len(declared) - 1)] if isinstance(declared, list) else declared
        if not isinstance(selected, dict):
            raise RuntimeError("FIXTURE_GRAPH_OUTCOME_INVALID: '" + str(occurrence_key) + "'.")
        referenced_value = None
        outcome_reference = selected.get("outcomeRef")
        if isinstance(outcome_reference, str):
            catalog = _OPTIONS.get("graphOutcomeCatalog") or {}
            if outcome_reference not in catalog:
                raise RuntimeError("FIXTURE_GRAPH_OUTCOME_REFERENCE_MISSING: '" + outcome_reference + "'")
            referenced_value = catalog[outcome_reference]
        fixture_value = selected.get("outcomeValue")
        if fixture_value is None:
            fixture_value = referenced_value
        if fixture_value is None:
            fixture_value = copy.deepcopy(_OPTIONS.get("rootInput"))
            if isinstance(fixture_value, dict) and isinstance(selected.get("outcomeVariant"), str):
                fixture_value["outcomeVariant"] = selected["outcomeVariant"]
            elif fixture_value is None:
                fixture_value = copy.deepcopy(input_value)
        fixture_value = _resolve_fixture_graph_value(fixture_value, _OPTIONS.get("graphOutcomeCatalog") or {})
        return {
            "outcomeValue": copy.deepcopy(fixture_value),
            **({"outcomeVariant": selected["outcomeVariant"]} if selected.get("outcomeVariant") else {}),
            **({"disposition": selected["disposition"]} if selected.get("disposition") else {}),
        }
    expression = configuration if isinstance(configuration, dict) and isinstance(configuration.get("op"), str) else None
    if expression is None and isinstance(configuration, dict):
        binding = configuration.get("binding")
        if isinstance(binding, dict) and isinstance(binding.get("configuration"), dict):
            candidate = binding["configuration"].get("expression")
            if isinstance(candidate, dict) and isinstance(candidate.get("op"), str):
                expression = candidate
    if expression is not None:
        return _evaluate_pure(context.cell_id, expression, input_value, context)
    if isinstance(configuration, dict) and configuration.get("kind") == "invoke-port" and isinstance(configuration.get("binding"), dict):
        source_binding = configuration["binding"]
        platform_capability_id = source_binding.get("platformCapabilityId")
        source_configuration = source_binding.get("configuration") if isinstance(source_binding.get("configuration"), dict) else {}
        if platform_capability_id == "sda-declarative-value-port.v1":
            return {"outcomeValue": copy.deepcopy(source_configuration.get("outcome"))}
        read_provider = _OPTIONS.get("readProvider")
        if isinstance(source_configuration.get("statement"), str) and read_provider is not None:
            return {"outcomeValue": read_provider(input_value, context)}
        declared_port = _DECLARED_PORTS.get(platform_capability_id)
        if declared_port is not None:
            return {"outcomeValue": _invoke_declared_port(declared_port, source_configuration, input_value, context)}
        raise RuntimeError("MISSING_SDA_PLATFORM_CAPABILITY: '" + str(platform_capability_id) + "'")
    if isinstance(cell, dict) and isinstance(cell.get("execution"), dict) and cell["execution"].get("authorityId") == "mechanic:identity.v1":
        return {"outcomeValue": input_value, "outcomeVariant": "VALUE"}
    raise RuntimeError("UNDECLARED_EXECUTION_MECHANIC: '" + str(context.cell_id) + "'.")

def _project_edge_binding(binding_authority_id, edge_input, root_input):
    edge = _EDGE_BINDINGS.get(binding_authority_id)
    if edge is None:
        raise RuntimeError("EDGE_BINDING_REALIZATION_MISSING: '" + str(binding_authority_id) + "'.")
    if edge["kind"] == "declarative-output":
        return copy.deepcopy(edge["output"])
    return edge["evaluate"]({"input": edge_input, "root": root_input})

def _execution_result(result):
    executions = []
    for testimony in result.get("cellTestimony", []):
        if not isinstance(testimony, dict):
            continue
        cell = _CELL_BY_ID.get(str(testimony.get("cellId")))
        if not isinstance(cell, dict) or cell.get("altitude") != "scenario":
            continue
        executions.append({
            "executionId": testimony.get("cellExecutionId"),
            "rootExecutionId": testimony.get("rootExecutionId", _OPTIONS.get("rootExecutionId")),
            "parentExecutionId": None,
            "scenarioId": _scenario_id_for_cell(str(testimony.get("cellId"))),
            "disposition": testimony.get("disposition"),
            "outcome": None,
        })
    return {
        "disposition": "terminated" if result.get("disposition") == "completed" else result.get("disposition"),
        "outcome": copy.deepcopy(result.get("outcome")),
        "outcomeVariant": result.get("outcomeVariant"),
        "executions": executions,
        "observations": [],
        "graphExecution": result,
    }

def execute_capability(input_value, options=None):
    resolved = dict(options or {})
    effect_context = resolved.get("effectContext") or create_governed_effect_context()
    root_execution_id = resolved.get("rootExecutionId") or ("execution:" + str(CANONICAL_GRAPH["graphId"]))
    _OPTIONS.update({
        "rootInput": input_value,
        "rootExecutionId": root_execution_id,
        "portOutcomes": resolved.get("portOutcomes") or {},
        "graphOutcomes": resolved.get("graphOutcomes") or {},
        "graphOutcomeCatalog": resolved.get("graphOutcomeCatalog") or {},
        "effectContext": effect_context,
        "readProvider": _DECLARED_READ_FACTORY({"readQuery": resolved.get("readQuery")}) if _DECLARED_READ_FACTORY is not None else None,
    })
    _OCCURRENCES.clear()
    _FIXTURE_OCCURRENCES.clear()
    providers = {profile_id: _invoke for profile_id in PROFILE_IDS}
    scheduler = SemanticExecutionGraphScheduler(
        _plan(),
        providers,
        lambda binding_authority_id, edge_input: _project_edge_binding(binding_authority_id, edge_input, input_value),
        _build_contract_admission(CONTRACT_CATALOG),
    )
    return _execution_result(scheduler.execute(copy.deepcopy(input_value), root_execution_id))

def run_fixture(fixture_id, options=None):
    fixtures = FIXTURES.get("fixtures") or []
    fixture = next((item for item in fixtures if isinstance(item, dict) and item.get("fixtureId") == fixture_id), None)
    if fixture is None:
        raise RuntimeError("UNKNOWN_PROJECTED_FIXTURE: '" + str(fixture_id) + "'.")
    graph_outcome_catalog = {**(FIXTURES.get("graphOutcomeCatalog") or {}), **(fixture.get("graphOutcomeCatalog") or {})}
    return execute_capability(
        _resolve_fixture_graph_value(fixture.get("input"), graph_outcome_catalog),
        {
            **dict(options or {}),
            "portOutcomes": {**(FIXTURES.get("portOutcomes") or {}), **(fixture.get("portOutcomes") or {})},
            "graphOutcomes": fixture.get("graphOutcomes") or {},
            "graphOutcomeCatalog": graph_outcome_catalog,
        },
    )

FIXTURE_IDS = tuple(str(item.get("fixtureId")) for item in (FIXTURES.get("fixtures") or []) if isinstance(item, dict))

def _at_path(source, path):
    value = source
    for segment in [part for part in path.split(".") if part]:
        if isinstance(value, list) and segment.isdigit():
            value = value[int(segment)]
        elif isinstance(value, dict):
            value = value.get(segment)
        else:
            return None
    return value

def _contains(actual, expected):
    if isinstance(actual, list):
        return expected in actual
    if isinstance(actual, str):
        return str(expected) in actual
    return False

def _fixture_findings(result, expected):
    findings = []
    if result.get("disposition") != expected.get("disposition"):
        findings.append("DISPOSITION_MISMATCH")
    executions = [item for item in (result.get("executions") or []) if isinstance(item, dict)]
    if [item.get("scenarioId") for item in executions] != expected.get("scenarioSequence"):
        findings.append("SCENARIO_SEQUENCE_MISMATCH")
    if expected.get("outcomeVariant") and result.get("outcomeVariant") != expected.get("outcomeVariant"):
        findings.append("OUTCOME_VARIANT_MISMATCH")
    for assertion in expected.get("outcomeAssertions") or []:
        if not isinstance(assertion, dict):
            continue
        actual = _at_path(result.get("outcome"), str(assertion.get("path")))
        operation = assertion.get("operator")
        expected_value = assertion.get("value")
        if operation == "equals":
            matches = actual == expected_value
        elif operation == "contains":
            matches = _contains(actual, expected_value)
        elif operation == "not-contains":
            matches = not _contains(actual, expected_value)
        else:
            matches = False
        if not matches:
            findings.append("OUTCOME_ASSERTION_FAILED:" + str(assertion.get("path")))
    return findings

def prove():
    results = []
    admitted = True
    for fixture in FIXTURES.get("fixtures") or []:
        if not isinstance(fixture, dict) or not isinstance(fixture.get("expected"), dict):
            raise RuntimeError("Fixture is invalid")
        result = run_fixture(str(fixture.get("fixtureId")))
        findings = _fixture_findings(result, fixture["expected"])
        admitted = admitted and not findings
        results.append({
            "fixtureId": fixture.get("fixtureId"),
            "disposition": "PASS" if not findings else "FAIL",
            "actualDisposition": result.get("disposition"),
            "actualScenarioSequence": [item.get("scenarioId") for item in (result.get("executions") or []) if isinstance(item, dict)],
            "actualOutcome": result.get("outcome"),
            "findings": findings,
        })
    return {
        "proofType": "projected-python-consumer-conformance.v1",
        "projectionTarget": "python",
        "mechanicResolution": "RESOLVED",
        "executableOrigin": "PROJECTED_ONLY",
        "fixtures": results,
        "disposition": "ADMITTED" if admitted else "REJECTED",
    }

def value_at(source, dotted_path=""):
    return sfx_value_at(source, dotted_path)

def cli(argv=None):
    arguments = list(sys.argv[1:] if argv is None else argv)
    if arguments and arguments[0] == "--test":
        proof = prove()
        print(json.dumps(proof, separators=(",", ":"), ensure_ascii=False))
        return 0 if proof["disposition"] == "ADMITTED" else 1
    if arguments and arguments[0].startswith("--fixture="):
        fixture_id = arguments[0][len("--fixture="):]
        result = run_fixture(fixture_id)
        print(json.dumps(result, separators=(",", ":"), ensure_ascii=False))
        fixture = next((item for item in (FIXTURES.get("fixtures") or []) if isinstance(item, dict) and item.get("fixtureId") == fixture_id), None)
        expected = fixture.get("expected") if isinstance(fixture, dict) else None
        return 0 if isinstance(expected, dict) and result.get("disposition") == expected.get("disposition") else 1
    if len(arguments) != 1:
        raise ValueError("Expected one JSON-encoded canonical input argument or --test")
    result = execute_capability(json.loads(arguments[0]))
    print(json.dumps(result, separators=(",", ":"), ensure_ascii=False))
    if result.get("disposition") != "terminated":
        return 1
    outcome = result.get("outcome")
    return 1 if isinstance(outcome, dict) and outcome.get("interfaceExitDisposition") == "NONZERO" else 0

